//! Format step 2 to 3, generated by `cargo run migration snapshot`.

use crate::{v2, v3};
use migration_core::{MigrationError, Upgrade, format_migration};

format_migration! {
	2 => 3,
	session: v2::SessionState,
}

impl Upgrade for v2::RetiredMarks {
	type Next = v3::RetiredMarks;
	fn upgrade(self) -> Result<Self::Next, MigrationError> {
		let v2::RetiredMarks { retired_up_to, retired_runs } = self;
		Ok(v3::RetiredMarks {
			retired_up_to,
			retired_runs,
			taken_back: Default::default(),
		})
	}
}

impl Upgrade for v2::SessionState {
	type Next = v3::SessionState;
	fn upgrade(self) -> Result<Self::Next, MigrationError> {
		let v2::SessionState {
			peer_id,
			user_id,
			head_rev,
			last_broadcast_rev,
			redo_stack,
			next_node_counter,
			last_hot_sequence,
			view_settings,
			network_view_settings,
			retired_marks,
			clock_counter,
		} = self;
		Ok(v3::SessionState {
			peer_id,
			user_id,
			head_rev,
			last_broadcast_rev,
			redo_stack,
			next_node_counter,
			last_hot_sequence,
			view_settings,
			network_view_settings,
			retired_marks: Upgrade::upgrade(retired_marks)?,
			clock_counter,
			shared: false,
		})
	}
}
